<?php
declare(strict_types=1); require dirname(__DIR__).'/app/bootstrap.php'; $pdo=Database::connection();$programs=$pdo->query("SELECT * FROM umrah_programs WHERE status='active' ORDER BY departure_at")->fetchAll();$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();$name=trim($_POST['name']??'');$phone=preg_replace('/[^0-9+]/','',$_POST['phone']??'');$people=max(1,min(50,(int)($_POST['people']??1)));$city=trim($_POST['city']??'');$date=$_POST['expected_date']??null;$notes=trim($_POST['notes']??'');$programId=(int)($_POST['program_id']??0);$validProgram=$programId===0;foreach($programs as $program){if((int)$program['id']===$programId)$validProgram=true;}if(!$validProgram)$error='برنامج العمرة المحدد غير متاح.';if(mb_strlen($name)<3||strlen($phone)<8)$error='يرجى إدخال الاسم ورقم هاتف صحيح.';else try{$pdo->beginTransaction();$pdo->prepare('INSERT INTO customers(full_name,phone) VALUES(?,?) ON DUPLICATE KEY UPDATE full_name=VALUES(full_name)')->execute([$name,$phone]);$c=$pdo->prepare('SELECT id FROM customers WHERE phone=?');$c->execute([$phone]);$cid=(int)$c->fetchColumn();$ref='UMR-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$stmt=$pdo->prepare('INSERT INTO umrah_requests(reference_code,customer_id,program_id,people_count,city,expected_date,service_type,notes) VALUES(?,?,?,?,?,?,?,?)');$stmt->execute([$ref,$cid,$programId?:null,$people,$city,$date?:null,$programId?'برنامج محدد':'عمرة مخصصة',$notes]);$pdo->commit();$success=$ref;$msg="طلب عمرة%0Aالمرجع: {$ref}%0Aالاسم: ".rawurlencode($name)."%0Aالهاتف: ".rawurlencode($phone)."%0Aعدد الأشخاص: {$people}";$wa='https://wa.me/'.$config['whatsapp'].'?text='.$msg;}catch(Throwable){if($pdo->inTransaction())$pdo->rollBack();$error='تعذر تسجيل الطلب حالياً.';}}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>برامج العمرة | أصل المتصدر</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="site-header"><a class="brand" href="/"><span class="brand-mark">م</span><b>أصل المتصدر</b></a><a href="/">الرئيسية</a></header><main class="section"><span class="eyebrow">رحلة إيمانية ميسّرة</span><h1>برامج العمرة</h1><?php if(!$programs):?><div class="empty-state">لا توجد برامج عمرة منشورة حالياً. يمكنك إرسال طلب عمرة مخصص.</div><?php else:?><div class="trip-grid"><?php foreach($programs as $p):?><article class="trip-card"><h3><?=e($p['title'])?></h3><p><?=e($p['description'])?></p><p><?=e($p['duration_days']?:'—')?> يوم · <?=e($p['departure_at']?:'موعد يحدد لاحقاً')?></p><b><?=e($p['price']!==null?money($p['price']).' '.$p['currency']:'السعر عند الطلب')?></b><a class="btn btn-outline full" href="#request">اطلب هذا البرنامج</a></article><?php endforeach;?></div><?php endif;?><section class="panel" id="request"><h2>طلب عمرة مخصص</h2><?php if($error):?><p class="notice"><?=e($error)?></p><?php endif;?><?php if($success):?><p class="notice">تم تسجيل طلبك بالرقم <?=e($success)?>. <a href="<?=e($wa)?>" target="_blank" rel="noopener">فتح واتساب</a></p><?php else:?><form method="post" class="trip-search" style="grid-template-columns:repeat(2,1fr)"><input type="hidden" name="_csrf" value="<?=e(Security::csrf())?>"><label>الاسم<input name="name" required></label><label>الهاتف<input name="phone" required></label><label>عدد الأشخاص<input type="number" name="people" min="1" value="1"></label><label>المدينة<input name="city"></label><label>التاريخ المتوقع<input type="date" name="expected_date"></label><label>البرنامج<select name="program_id"><option value="">عمرة مخصصة</option><?php foreach($programs as $p):?><option value="<?=(int)$p['id']?>"><?=e($p['title'])?></option><?php endforeach;?></select></label><label style="grid-column:1/-1">ملاحظات<textarea name="notes"></textarea></label><button class="btn btn-primary" type="submit">إرسال الطلب</button></form><?php endif;?></section></main></body></html>